
let usuarios = JSON.parse(
    localStorage.getItem("usuarios") || "[]"
    );

    let publicacoes = JSON.parse(
        localStorage.getItem("publicacoes") || "[]"
        );

        let usuarioAtual = localStorage.getItem("usuarioAtual");

        // SALVAR DADOS
        function salvar() {
            localStorage.setItem("usuarios", JSON.stringify(usuarios));
                localStorage.setItem("publicacoes", JSON.stringify(publicacoes));
                }

                // CADASTRAR
                function cadastrar() {
                    const nome = document.getElementById("nome").value.trim();
                        const senha = document.getElementById("senha").value;

                            if (!nome || senha.length < 6) {
                                    alert("Informe um usuário e uma senha com pelo menos 6 caracteres.");
                                            return;
                                                }

                                                    if (usuarios.some(u => u.nome === nome)) {
                                                            alert("Usuário já cadastrado!");
                                                                    return;
                                                                        }

                                                                            usuarios.push({
                                                                                    nome,
                                                                                            senha,
                                                                                                    seguindo: []
                                                                                                        });

                                                                                                            salvar();
                                                                                                                alert("Conta criada! Agora entre.");
                                                                                                                }

                                                                                                                // ENTRAR
                                                                                                                function entrar() {
                                                                                                                    const nome = document.getElementById("nome").value.trim();
                                                                                                                        const senha = document.getElementById("senha").value;

                                                                                                                            const usuario = usuarios.find(
                                                                                                                                    u => u.nome === nome && u.senha === senha
                                                                                                                                        );

                                                                                                                                            if (!usuario) {
                                                                                                                                                    document.getElementById("aviso").textContent =
                                                                                                                                                                "Usuário ou senha incorretos.";
                                                                                                                                                                        return;
                                                                                                                                                                            }

                                                                                                                                                                                usuarioAtual = nome;
                                                                                                                                                                                    localStorage.setItem("usuarioAtual", nome);

                                                                                                                                                                                        abrirSistema();
                                                                                                                                                                                        }

                                                                                                                                                                                        // ABRIR SISTEMA
                                                                                                                                                                                        function abrirSistema() {
                                                                                                                                                                                            document.getElementById("login").classList.add("hidden");
                                                                                                                                                                                                document.getElementById("app").classList.remove("hidden");

                                                                                                                                                                                                    mostrarPagina("inicio");
                                                                                                                                                                                                        mostrarPublicacoes();
                                                                                                                                                                                                        }

                                                                                                                                                                                                        // SAIR
                                                                                                                                                                                                        function sair() {
                                                                                                                                                                                                            localStorage.removeItem("usuarioAtual");
                                                                                                                                                                                                                usuarioAtual = null;

                                                                                                                                                                                                                    document.getElementById("app").classList.add("hidden");
                                                                                                                                                                                                                        document.getElementById("login").classList.remove("hidden");
                                                                                                                                                                                                                        }

                                                                                                                                                                                                                        // NAVEGAÇÃO
                                                                                                                                                                                                                        function mostrarPagina(pagina) {
                                                                                                                                                                                                                            ["inicio", "explorar", "criar", "perfil"].forEach(id => {
                                                                                                                                                                                                                                    document.getElementById(id).classList.add("hidden");
                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                            document.getElementById(pagina).classList.remove("hidden");

                                                                                                                                                                                                                                                if (pagina === "inicio") mostrarPublicacoes();
                                                                                                                                                                                                                                                    if (pagina === "perfil") mostrarPerfil();
                                                                                                                                                                                                                                                        if (pagina === "explorar") pesquisar();
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        // PUBLICAR
                                                                                                                                                                                                                                                        function publicar() {
                                                                                                                                                                                                                                                            const arquivo = document.getElementById("foto").files[0];
                                                                                                                                                                                                                                                                const legenda = document.getElementById("legenda").value.trim();

                                                                                                                                                                                                                                                                    if (!arquivo || !arquivo.type.startsWith("image/")) {
                                                                                                                                                                                                                                                                            alert("Escolha uma imagem válida!");
                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                            const leitor = new FileReader();

                                                                                                                                                                                                                                                                                                leitor.onload = function() {
                                                                                                                                                                                                                                                                                                        publicacoes.unshift({
                                                                                                                                                                                                                                                                                                                    id: Date.now(),
                                                                                                                                                                                                                                                                                                                                usuario: usuarioAtual,
                                                                                                                                                                                                                                                                                                                                            imagem: leitor.result,
                                                                                                                                                                                                                                                                                                                                                        legenda,
                                                                                                                                                                                                                                                                                                                                                                    curtidas: [],
                                                                                                                                                                                                                                                                                                                                                                                comentarios: []
                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                salvar();

                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("foto").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("legenda").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarPagina("inicio");
                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Publicação realizada!");
                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                        leitor.readAsDataURL(arquivo);
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                        // MOSTRAR PUBLICAÇÕES
                                                                                                                                                                                                                                                                                                                                                                                                                                        function mostrarPublicacoes() {
                                                                                                                                                                                                                                                                                                                                                                                                                                            const feed = document.getElementById("feed");
                                                                                                                                                                                                                                                                                                                                                                                                                                                feed.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                    publicacoes.forEach((p, index) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            const curtido = p.curtidas.includes(usuarioAtual);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const post = document.createElement("article");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            post.className = "post";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const header = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            header.className = "post-header";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    header.textContent = "👤 " + p.usuario;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const imagem = document.createElement("img");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    imagem.src = p.imagem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            imagem.alt = "Publicação";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const info = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            info.className = "post-info";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const like = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            like.textContent = curtido ? "❤️ Curtido" : "🤍 Curtir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    like.onclick = () => curtir(index);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const commentButton = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    commentButton.textContent = "💬 Comentar";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            commentButton.onclick = () => comentar(index);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const legenda = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            legenda.textContent = p.usuario + ": " + p.legenda;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const total = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            total.textContent = p.curtidas.length + " curtidas";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    info.append(like, commentButton, total, legenda);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p.comentarios.forEach(c => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const comentario = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    comentario.className = "comentario";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                comentario.textContent = c.usuario + ": " + c.texto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            info.appendChild(comentario);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (p.usuario === usuarioAtual) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const excluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    excluir.textContent = "🗑️ Excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                excluir.onclick = () => excluirPost(index);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            info.appendChild(excluir);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            post.append(header, imagem, info);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    feed.appendChild(post);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // CURTIR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function curtir(index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const lista = publicacoes[index].curtidas;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (lista.includes(usuarioAtual)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        publicacoes[index].curtidas =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    lista.filter(u => u !== usuarioAtual);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                lista.push(usuarioAtual);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarPublicacoes();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // COMENTAR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function comentar(index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const texto = prompt("Escreva seu comentário:");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!texto || !texto.trim()) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        publicacoes[index].comentarios.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                usuario: usuarioAtual,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        texto: texto.trim()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarPublicacoes();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // EXCLUIR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function excluirPost(index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (confirm("Deseja excluir esta publicação?")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (publicacoes[index].usuario !== usuarioAtual) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        publicacoes.splice(index, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarPublicacoes();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // PERFIL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function mostrarPerfil() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarPagina("perfil");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const minhas = publicacoes.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p => p.usuario === usuarioAtual
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("dadosPerfil").innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h2>👤 ${usuarioAtual}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>${minhas.length} publicações</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p>Bem-vindo ao seu perfil!</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const area = document.getElementById("minhasPublicacoes");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        area.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            minhas.forEach(p => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const img = document.createElement("img");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            img.src = p.imagem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    img.style.width = "100%";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            img.style.marginBottom = "10px";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    area.appendChild(img);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // PESQUISAR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function pesquisar() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const busca = document.getElementById("pesquisa").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const resultados = document.getElementById("resultados");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            resultados.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                usuarios.filter(u =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        u.nome.toLowerCase().includes(busca)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ).forEach(u => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const div = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            div.className = "comentario";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const nome = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            nome.textContent = "👤 " + u.nome;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    div.appendChild(nome);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (u.nome !== usuarioAtual) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const botao = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const seguindo = u.seguindo.includes(usuarioAtual);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.textContent = seguindo ? "Seguindo" : "Seguir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.onclick = () => seguir(u.nome);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        div.appendChild(botao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        resultados.appendChild(div);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // SEGUIR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function seguir(nome) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const pessoa = usuarios.find(u => u.nome === nome);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!pessoa || nome === usuarioAtual) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.seguindo = pessoa.seguindo || [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (pessoa.seguindo.includes(usuarioAtual)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pessoa.seguindo = pessoa.seguindo.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                u => u !== usuarioAtual
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pessoa.seguindo.push(usuarioAtual);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pesquisar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // INICIALIZAÇÃO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (usuarioAtual && usuarios.some(u => u.nome === usuarioAtual)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    abrirSistema();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    